<?php
// Cancelled orders share the existing linked receipt ledger, so every return,
// cancellation and reversal uses the same remaining-original-order allowance.
function cancelled_order_batch($b){return str_starts_with($b['batch_ref']??'','CAN-');}
function cancelled_order_require(){if(!can_action('return_confirm'))throw new Exception('Your account cannot receive cancelled orders.');}
function cancelled_order_owner($b){cancelled_order_require();if(current_user()['role']!=='Admin'&&(int)$b['created_by']!==current_user()['id'])throw new Exception('Only the preparer or an Admin may submit or change this cancellation receipt.');}
function cancelled_order_lookup($platform,$order){
 $platform=stock_platform($platform);$order=trim((string)$order);if($order===''||strlen($order)>100)throw new Exception('Enter the original Order ID, up to 100 characters.');
 $q=db()->prepare("SELECT o.id,o.order_id,o.product_id,o.qty,o.txn_date,o.source_item,o.created_at,p.name,p.master_sku FROM outflows o JOIN products p ON p.id=o.product_id WHERE o.platform=? AND o.order_id=? AND o.type='Order' AND o.reversed_by_request IS NULL AND o.qty>0 ORDER BY o.id");$q->execute([$platform,$order]);$posted=$q->fetchAll();if(!$posted)throw new Exception('No active posted order was found for this platform and Order ID. Unposted or fully reversed orders cannot add stock.');
 $order=trim($posted[0]['order_id']);$items=[];foreach($posted as $r){$pid=(int)$r['product_id'];if(!isset($items[$pid]))$items[$pid]=['product_id'=>$pid,'name'=>$r['name'],'sku'=>$r['master_sku'],'source_items'=>[],'posted'=>[],'latest_date'=>$r['txn_date']];$items[$pid]['posted'][]=array_intersect_key($r,array_flip(['id','product_id','qty','txn_date','source_item','created_at']));if($r['source_item']!=='')$items[$pid]['source_items'][$r['source_item']]=$r['source_item'];$items[$pid]['latest_date']=max($items[$pid]['latest_date'],$r['txn_date']);}
 foreach($items as $pid=>&$item){$item+=order_return_balance($platform,$order,$pid);$item['signature']=hash('sha256',json_encode($item['posted']));$item['source_items']=array_values($item['source_items']);}unset($item);return ['platform'=>$platform,'order'=>$order,'items'=>$items];
}
function cancelled_order_line_key($platform,$order,$pid){return hash('sha256',json_encode([$platform,$order,(int)$pid]));}
function cancelled_order_cart(){return $_SESSION['cancelled_order_cart_'.current_user()['id']]??['orders'=>[],'date'=>date('Y-m-d'),'reason'=>''];}
function cancelled_order_store($cart){$_SESSION['cancelled_order_cart_'.current_user()['id']]=$cart;}
function cancelled_order_cart_input($input){$c=cancelled_order_cart();$c['date']=$input['txn_date']??$c['date'];$c['reason']=trim((string)($input['reason']??$c['reason']));foreach($c['orders'] as &$o)foreach($o['items'] as &$item){$key=cancelled_order_line_key($o['platform'],$o['order'],$item['product_id']);$v=$input['lines'][$key]??[];$item['selected']=!empty($v['selected']);$item['qty']=$v['qty']??($item['qty']??$item['remaining']);$item['condition']=$v['condition']??($item['condition']??'Good Item');}unset($o,$item);cancelled_order_store($c);return $c;}
function cancelled_order_add($input){cancelled_order_require();$c=cancelled_order_cart_input($input);if(!empty($input['remove_order'])){unset($c['orders'][$input['remove_order']]);cancelled_order_store($c);return;}
 $o=cancelled_order_lookup($input['platform']??'', $input['order_id']??'');$key=hash('sha256',json_encode([$o['platform'],$o['order']]));if(isset($c['orders'][$key]))throw new Exception('This order is already in the batch. Select its items below.');if(count($c['orders'])>=30)throw new Exception('Use up to 30 orders per cancellation batch.');if(!array_filter($o['items'],fn($i)=>$i['remaining']>0))throw new Exception('All quantities in this order have already been returned or cancelled.');foreach($o['items'] as &$i){$i['selected']=$i['remaining']>0;$i['qty']=$i['remaining']>0?$i['remaining']:1;$i['condition']='Good Item';}unset($i);$c['orders'][$key]=$o;cancelled_order_store($c);
}
function cancelled_order_validate_row($row){$o=cancelled_order_lookup($row['platform'],$row['order']);$i=$o['items'][(int)$row['product_id']]??null;if(!$i||!hash_equals($i['signature'],(string)($row['source_signature']??'')))throw new Exception('The posted order changed. Find the order again before receiving these items.');if($row['date']<$i['latest_date'])throw new Exception('Received date cannot precede the original outflow date.');require_open_inventory_date($row['date']);process_reason($row['remarks']);}
function cancelled_order_stage($input){cancelled_order_require();$c=cancelled_order_cart_input($input);$date=process_date($c['date']);require_open_inventory_date($date);$reason=process_reason($c['reason']);$rows=[];
 foreach($c['orders'] as $o){$fresh=cancelled_order_lookup($o['platform'],$o['order']);foreach($o['items'] as $pid=>$item){if(empty($item['selected']))continue;$f=$fresh['items'][$pid]??null;if(!$f||!hash_equals($f['signature'],$item['signature']))throw new Exception('The original posted order changed. Remove and find that order again.');$rows[]=['row'=>count($rows)+1,'date'=>$date,'order'=>$o['order'],'platform'=>$o['platform'],'product_id'=>(int)$pid,'item'=>$f['name'],'qty'=>whole_number($item['qty'],'Received quantity',1),'condition'=>$item['condition'],'remarks'=>$reason,'source_signature'=>$f['signature'],'transaction_kind'=>'Cancelled Order'];}}
 if(!$rows)throw new Exception('Select at least one cancelled item to receive.');if(count($rows)>200)throw new Exception('Use up to 200 product lines per batch.');$probe=['batch_ref'=>'CAN-VALIDATE','revision'=>1,'status'=>'Review','rows_json'=>json_encode($rows)];$a=return_analysis($probe);if($a['errors'])throw new Exception(implode(' · ',$a['errors']));
 return process_transaction(function()use($rows,$input){$id=(int)($input['batch_id']??0);if($id){$b=return_batch($id,true);if(!cancelled_order_batch($b)||$b['status']!=='Review')throw new Exception('Only an unposted cancellation receipt can be corrected.');cancelled_order_owner($b);if((int)$b['revision']!==(int)($input['revision']??0))throw new Exception('This review changed. Reopen it before saving.');db()->prepare('UPDATE return_batches SET rows_json=?,revision=revision+1 WHERE id=?')->execute([json_encode($rows),$id]);}
 else{db()->prepare('INSERT INTO return_batches(batch_ref,filename,rows_json,created_by) VALUES(?,?,?,?)')->execute([next_ref('CAN').'-'.bin2hex(random_bytes(3)),'Cancelled Orders — Order Lookup',json_encode($rows),current_user()['id']]);$id=(int)db()->lastInsertId();}
 cancelled_order_store(['orders'=>[],'date'=>date('Y-m-d'),'reason'=>'']);inflow_sync_return_history($id);audit('Review cancelled orders','Return',(string)$id,count($rows).' linked product lines; no inventory added.');return $id;});
}
function cancelled_order_load_edit($b){cancelled_order_owner($b);$c=['orders'=>[],'date'=>date('Y-m-d'),'reason'=>'','editing'=>(int)$b['id']];foreach(json_decode($b['rows_json'],true) as $r){$key=hash('sha256',json_encode([$r['platform'],$r['order']]));if(!isset($c['orders'][$key])){$o=cancelled_order_lookup($r['platform'],$r['order']);foreach($o['items'] as &$i){$i['selected']=false;$i['qty']=max(1,$i['remaining']);$i['condition']='Good Item';}unset($i);$c['orders'][$key]=$o;}$item=&$c['orders'][$key]['items'][$r['product_id']];$item['selected']=true;$item['qty']=$r['qty'];$item['condition']=$r['condition'];unset($item);$c['date']=$r['date'];$c['reason']=$r['remarks'];}cancelled_order_store($c);return $c;}
